						<span class="badge badge-xs badge-ghost">Milestone 5</span>
					</div>
					<p class="text-xs text-base-content/70">
						Mermaid-powered visual deal closing roadmaps, customer onboarding journeys, and technical architecture flows.
					</p>
				</a>

				<!-- Deal Emails -->
				<a href="/emails" class="card bg-base-100 border border-base-300 hover:border-base-content/40 transition-colors p-4 space-y-2 block text-decoration-none">
					<div class="flex items-center justify-between">
						<span class="font-bold text-sm text-base-content">Deal Emails</span>
						<span class="badge badge-xs badge-ghost">Milestone 5</span>
					</div>
					<p class="text-xs text-base-content/70">
						Post-discovery recaps, champion enablement drafts, executive proposals, and contract negotiation follow-ups.
					</p>
				</a>

				<!-- Pitch Decks -->
				<a href="/presentations" class="card bg-base-100 border border-base-300 hover:border-base-content/40 transition-colors p-4 space-y-2 block text-decoration-none">
					<div class="flex items-center justify-between">
						<span class="font-bold text-sm text-base-content">Pitch Decks</span>
						<span class="badge badge-xs badge-ghost">Milestone 5</span>
					</div>
					<p class="text-xs text-base-content/70">
						Executive briefings, solution outlines, commercial ROI cases, and PowerPoint (.pptx) exports.
					</p>
				</a>

				<!-- Deal Orchestrator DAG -->
				<a href="/agent" class="card bg-base-100 border border-base-300 hover:border-base-content/40 transition-colors p-4 space-y-2 block text-decoration-none">
					<div class="flex items-center justify-between">
						<span class="font-bold text-sm text-base-content">Deal Orchestrator</span>
						<span class="badge badge-xs badge-ghost">Milestone 4</span>
					</div>
					<p class="text-xs text-base-content/70">
						Autonomous DAG execution engine running parallel sales tools with self-healing retries and state tracking.
					</p>
				</a>

				<!-- Deal Rooms / Share -->
				<a href="/deals" class="card bg-base-100 border border-base-300 hover:border-base-content/40 transition-colors p-4 space-y-2 block text-decoration-none">
					<div class="flex items-center justify-between">
						<span class="font-bold text-sm text-base-content">Deal Rooms</span>
						<span class="badge badge-xs badge-ghost">Milestone 3</span>
					</div>
					<p class="text-xs text-base-content/70">
						Stable public URLs for prospective buyers to review read-only collateral without editing permissions.
					</p>
				</a>
			</div>
		</div>
	</div>

	<script>
		const healthBtn = document.getElementById('btn-health');
		const testLlmBtn = document.getElementById('btn-test-llm');
		const promptInput = document.getElementById('prompt-input');
		const outputBox = document.getElementById('output-box');
		const statusBadge = document.getElementById('backend-status-badge');
		const latencyLabel = document.getElementById('latency-label');

		function setStatus(text, badgeClass) {
			if (statusBadge) {
				statusBadge.textContent = text;
				statusBadge.className = 'badge text-xs ' + badgeClass;
			}
		}

		healthBtn?.addEventListener('click', async () => {
			const start = performance.now();
			setStatus('Checking...', 'badge-warning');
			if (outputBox) outputBox.textContent = 'Calling proxy: /health ...';
			if (latencyLabel) latencyLabel.textContent = '';

			try {
				const res = await fetch('/health');
				const data = await res.json();
				const duration = Math.round(performance.now() - start);

				if (res.ok) {
					setStatus(`HTTP ${res.status} OK`, 'badge-success');
					if (outputBox) outputBox.textContent = JSON.stringify(data, null, 2);
					if (latencyLabel) latencyLabel.textContent = `${duration}ms`;
				} else {
					setStatus(`HTTP ${res.status}`, 'badge-error');
					if (outputBox) outputBox.textContent = JSON.stringify(data, null, 2);
				}
			} catch (err) {
				setStatus('Failed', 'badge-error');
				if (outputBox) {
					outputBox.textContent = `Proxy error: ${err.message}\nMake sure FastAPI is running on port 8000.`;
				}
			}
		});

		testLlmBtn?.addEventListener('click', async () => {
			const start = performance.now();
			setStatus('Generating...', 'badge-warning');
			if (testLlmBtn) testLlmBtn.disabled = true;
			if (outputBox) outputBox.textContent = 'Calling proxy: POST /api/test-llm ...';
			if (latencyLabel) latencyLabel.textContent = '';

			const prompt = (promptInput?.value || '').trim() || 'Summarize our value proposition.';

			try {
				const res = await fetch('/api/test-llm', {
					method: 'POST',
					headers: { 'Content-Type': 'application/json' },
					body: JSON.stringify({ prompt }),
				});
				const data = await res.json();
				const duration = Math.round(performance.now() - start);

				if (res.ok) {
					setStatus(`HTTP ${res.status} OK`, 'badge-success');
					if (outputBox) outputBox.textContent = JSON.stringify(data, null, 2);
					if (latencyLabel) latencyLabel.textContent = `${duration}ms`;
				} else {
					setStatus(`HTTP ${res.status}`, 'badge-error');
					if (outputBox) outputBox.textContent = JSON.stringify(data, null, 2);
				}
			} catch (err) {
				setStatus('Error', 'badge-error');
				if (outputBox) {
					outputBox.textContent = `Proxy request error: ${err.message}\nEnsure backend is running on port 8000.`;
				}
			} finally {
				if (testLlmBtn) testLlmBtn.disabled = false;
			}
		});
	</script>
</Layout>

