@import "tailwindcss";
@plugin "daisyui" {
  themes: caramellatte --default;
}

/* 3D Flip Card Utility Styles */
.perspective-1000 {
  perspective: 1000px;
}
.transform-style-3d {
  transform-style: preserve-3d;
}
.backface-hidden {
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}
.rotate-y-180 {
  transform: rotateY(180deg);
}

.flip-card {
  perspective: 1000px;
}

.flip-card-inner {
  transition: transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
  transform-style: preserve-3d;
  position: relative;
}

.flip-card.is-flipped .flip-card-inner {
  transform: rotateY(180deg);
}

/* Smooth Slide Transitions for PPT */
.slide-enter {
  animation: slideFadeIn 0.35s ease-out forwards;
}

@keyframes slideFadeIn {
  from {
    opacity: 0;
    transform: scale(0.985);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

