								<div class="font-bold text-xs text-base-content">Pitch & ROI Presentation</div>
								<p class="text-[11px] text-base-content/70">
									Constructed 16:9 executive briefing deck incorporating MAP roadmap and cfo.ai payback.
								</p>
							</div>
							<div class="text-[10px] text-base-content/50 border-t border-base-300/60 pt-1">
								Consumes: Nodes [3, 4]
							</div>
						</div>
					</div>

				</div>
			</div>
		</div>
	</div>

	<script>
		const runBtn = document.getElementById('btn-run-dag');
		const resetBtn = document.getElementById('btn-reset-dag');
		const runBtnText = document.getElementById('run-btn-text');
		const statusBadge = document.getElementById('pipeline-status-badge');
		const latencyIndicator = document.getElementById('dag-latency-indicator');
		const nodes = [
			document.getElementById('node-1'),
			document.getElementById('node-2'),
			document.getElementById('node-3'),
			document.getElementById('node-4'),
			document.getElementById('node-5'),
			document.getElementById('node-6'),
		];

		function setNodeState(node, state) {
			if (!node) return;
			const badge = node.querySelector('.node-badge');
			if (state === 'pending') {
				node.classList.remove('border-primary', 'bg-primary/5');
				node.classList.add('opacity-50');
				if (badge) {
					badge.className = 'node-badge badge badge-xs badge-ghost';
					badge.textContent = 'Waiting';
				}
			} else if (state === 'running') {
				node.classList.remove('opacity-50');
				node.classList.add('border-primary', 'bg-primary/10');
				if (badge) {
					badge.className = 'node-badge badge badge-xs badge-warning';
					badge.textContent = 'Executing...';
				}
			} else if (state === 'completed') {
				node.classList.remove('bg-primary/10');
				node.classList.add('bg-base-200/80');
				if (badge) {
					badge.className = 'node-badge badge badge-xs badge-success';
					badge.textContent = '✓ Completed';
				}
			}
		}

		resetBtn?.addEventListener('click', () => {
			nodes.forEach((n) => setNodeState(n, 'pending'));
			if (statusBadge) {
				statusBadge.className = 'badge badge-sm badge-ghost';
				statusBadge.textContent = 'Standby';
			}
			if (latencyIndicator) latencyIndicator.textContent = '0.0s';
		});

		runBtn?.addEventListener('click', async () => {
			if (runBtn) (runBtn as HTMLButtonElement).disabled = true;
			if (runBtnText) runBtnText.textContent = 'Executing DAG...';
			if (statusBadge) {
				statusBadge.className = 'badge badge-sm badge-warning';
				statusBadge.textContent = 'Executing';
			}

			// Step 1: Root Node 1
			setNodeState(nodes[0], 'running');
			await new Promise((r) => setTimeout(r, 400));
			setNodeState(nodes[0], 'completed');

			// Step 2: Parallel Layer (Nodes 2, 3, 4)
			setNodeState(nodes[1], 'running');
			setNodeState(nodes[2], 'running');
			setNodeState(nodes[3], 'running');
			await new Promise((r) => setTimeout(r, 600));
			setNodeState(nodes[1], 'completed');
			setNodeState(nodes[2], 'completed');
			setNodeState(nodes[3], 'completed');

			// Step 3: Dependent Layer (Nodes 5, 6)
			setNodeState(nodes[4], 'running');
			setNodeState(nodes[5], 'running');
			await new Promise((r) => setTimeout(r, 500));
			setNodeState(nodes[4], 'completed');
			setNodeState(nodes[5], 'completed');

			if (statusBadge) {
				statusBadge.className = 'badge badge-sm badge-success';
				statusBadge.textContent = 'Pipeline Resolved';
			}
			if (latencyIndicator) latencyIndicator.textContent = '1.18s (Concurrent Execution)';
			if (runBtnText) runBtnText.textContent = 'Run Orchestrator';
			if (runBtn) (runBtn as HTMLButtonElement).disabled = false;
		});
	</script>
</Layout>

