---
import Layout from '../layouts/Layout.astro';
---

<Layout title="Objection Battlecards" description="Real-Time Competitive Objection Handling & AE Talk-Tracks">
	<div class="space-y-6 w-full">
		<!-- Header Toolbar -->
		<div class="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-base-300">
			<div>
				<div class="flex items-center gap-2.5">
					<h1 class="text-xl font-bold tracking-tight text-base-content">Objection Battlecards</h1>
					<span class="badge badge-sm badge-neutral" id="deck-counter-badge">Active Repository</span>
				</div>
				<p class="text-xs text-base-content/80 mt-1">
					Competitive objection handling and winning talk-tracks synthesized autonomously by the AI Sales Agent.
				</p>
			</div>
			<!-- Top-Right Actions -->
			<div class="flex items-center gap-2 self-start sm:self-auto shrink-0">
				<a href="/" class="btn btn-sm btn-neutral gap-1.5 font-semibold">
					<span>+ Generate with Agent</span>
				</a>
			</div>
		</div>

		<!-- LOADING STATE -->
		<div id="loading-state" class="py-16 text-center space-y-3">
			<span class="loading loading-spinner loading-md text-primary"></span>
			<p class="text-xs text-base-content/60 font-mono">Loading battlecards from agent artifact store...</p>
		</div>

		<!-- EMPTY STATE (Zero mock data) -->
		<div id="empty-state" class="hidden py-16 flex flex-col items-center justify-center text-center space-y-4">
			<div class="w-16 h-16 rounded-2xl bg-base-200 border-2 border-base-300 flex items-center justify-center text-3xl shadow-xs">
				🛡️
			</div>
			<div class="max-w-md space-y-1.5">
				<h3 class="font-bold text-base text-base-content">No Battlecards Generated Yet</h3>
				<p class="text-xs text-base-content/75 leading-relaxed">
					Battlecards are generated dynamically from your deal context. Direct the AI agent in the studio with your account notes and competitor objections to synthesize battlecards.
				</p>
			</div>
			<a href="/" class="btn btn-sm btn-neutral font-semibold">
				Go to AI Agent Studio ⚡
			</a>
		</div>

		<!-- REAL BATTLECARDS CONTAINER (Populated dynamically) -->
		<div id="cards-container" class="hidden space-y-6">
			<div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5" id="cards-grid">
				<!-- Dynamically injected -->
			</div>
		</div>
	</div>

	<script>
		const loadingState = document.getElementById('loading-state');
		const emptyState = document.getElementById('empty-state');
		const cardsContainer = document.getElementById('cards-container');
		const cardsGrid = document.getElementById('cards-grid');
		const counterBadge = document.getElementById('deck-counter-badge');

		async function loadBattlecards() {
			try {
				const res = await fetch('/api/artifacts');
				if (!res.ok) throw new Error('Failed to fetch artifacts');
				const artifacts = await res.json();
				const battlecardArtifacts = artifacts.filter((a: any) => a.type === 'battlecards');

				if (loadingState) loadingState.classList.add('hidden');

				if (!battlecardArtifacts.length) {
					if (emptyState) emptyState.classList.remove('hidden');
					return;
				}

				if (cardsContainer) cardsContainer.classList.remove('hidden');

				let totalCards = 0;
				let cardsHtml = '';

				battlecardArtifacts.forEach((art: any) => {
					const cards = art.content?.cards || [];
					totalCards += cards.length;

					cards.forEach((c: any) => {
						const tags = c.tags || c.key_differentiators || ['Verified Talk-Track'];
						cardsHtml += `
							<div class="card bg-base-100 border-2 border-base-300 p-5 rounded-2xl shadow-sm hover:border-primary/50 transition-all space-y-3.5 flex flex-col justify-between">
								<div class="space-y-2">
									<div class="flex items-center justify-between border-b border-base-200 pb-2.5">
										<span class="badge badge-xs badge-neutral font-bold uppercase tracking-wider">${c.category || 'Objection'}</span>
										<span class="text-[10px] font-mono text-base-content/60">${art.deal_context?.account_name || 'Account'}</span>
									</div>
									<h4 class="text-sm font-bold text-base-content leading-snug">
										"${c.objection_quote || c.objection}"
									</h4>
								</div>

								<div class="p-3 bg-base-200/80 rounded-xl border border-base-300 space-y-1">
									<span class="text-[10px] font-bold uppercase tracking-wider text-base-content/70">Winning Talk-Track:</span>
									<p class="text-xs text-base-content font-medium leading-relaxed">
										${c.winning_response || c.talk_track}
									</p>
								</div>

								<div class="flex flex-wrap gap-1.5 pt-1">
									${tags.map((t: string) => `<span class="badge badge-xs badge-outline">${t}</span>`).join('')}
								</div>
							</div>
						`;
					});
				});

				if (counterBadge) counterBadge.textContent = `${totalCards} Active Cards`;
				if (cardsGrid) cardsGrid.innerHTML = cardsHtml;
			} catch (err) {
				if (loadingState) loadingState.classList.add('hidden');
				if (emptyState) emptyState.classList.remove('hidden');
			}
		}

		loadBattlecards();
	</script>
</Layout>

