import Layout from '../layouts/Layout.astro';
---

<Layout title="BUST — Plan" description="AI Deal Planning & Execution">
	<div class="flex flex-col flex-1 w-full space-y-4">

		<!-- TOP BAR: ABSTRACTED DELIVERABLES & CONTROLS (OPEN ON DEMAND) -->
		<div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-3 border-b border-base-300">
