	</div>

	<!-- 3D FLIP CARD & CAROUSEL STYLES -->
	<style is:global>
		.perspective-1000 {
			perspective: 1000px;
		}
		.flip-card {
			perspective: 1000px;
		}
		.flip-card-inner {
			position: relative;
			width: 100%;
			height: 100%;
			transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
			transform-style: preserve-3d;
		}
		.flip-card-inner.is-flipped {
			transform: rotateY(180deg);
		}
		.backface-hidden {
			backface-visibility: hidden;
			-webkit-backface-visibility: hidden;
		}
		.rotate-y-180 {
			transform: rotateY(180deg);
		}
	</style>

	<script>
		let dealContext: any = {};
		let storedArtifacts: any = {};
		let activeTab: string = 'battlecards';
		let sidePanelOpen: boolean = true;

		// Stacked Deck state for side panel
		let sideCards: any[] = [];
		let sideCardOrder: number[] = [];

		const chatStream = document.getElementById('chat-stream');
		const chatForm = document.getElementById('chat-form');
		const chatInput = document.getElementById('chat-input') as HTMLInputElement;
		const sendBtn = document.getElementById('btn-send-directive');
		const resetBtn = document.getElementById('btn-reset-session');
		const welcomeTurn = document.getElementById('welcome-turn');
		const chips = document.querySelectorAll('.chat-chip');
		const dealTitleBadge = document.getElementById('deal-title-badge');

		// Side Panel elements
		const sidePanel = document.getElementById('side-panel');
		const btnCloseSide = document.getElementById('btn-close-side');
		const sidePanelTitle = document.getElementById('side-panel-title');
		const sideActiveAccount = document.getElementById('side-active-account');
		const btnOpenFullPage = document.getElementById('btn-open-full-page') as HTMLAnchorElement;
		const fullPageBtnText = document.getElementById('full-page-btn-text');
		const sideEmptyState = document.getElementById('side-empty-state');
		const sideDeliverableView = document.getElementById('side-deliverable-view');

		// App Dock elements
		const sideAppBtns = document.querySelectorAll('.side-app-btn');
		const appDockToggle = document.getElementById('app-dock-toggle');
		const appDockToggleIcon = document.getElementById('app-dock-toggle-icon');
		const appBadgeBc = document.getElementById('app-badge-bc');
		const appBadgeDeck = document.getElementById('app-badge-deck');
		const appBadgeEmail = document.getElementById('app-badge-email');
		const appBadgeMap = document.getElementById('app-badge-map');
		const appBadgeSuite = document.getElementById('app-badge-suite');

		// Toggle Side Panel State
		function setSidePanelState(open: boolean) {
			sidePanelOpen = open;
			if (!sidePanel) return;
			if (open) {
				sidePanel.classList.remove('hidden');
				if (appDockToggleIcon) appDockToggleIcon.textContent = '▶';
			} else {
				sidePanel.classList.add('hidden');
				if (appDockToggleIcon) appDockToggleIcon.textContent = '◀';
				// Deselect app buttons
				sideAppBtns.forEach((b) => b.classList.remove('ring-2', 'ring-primary', 'bg-base-200'));
			}
		}

		appDockToggle?.addEventListener('click', () => {
			setSidePanelState(!sidePanelOpen);
		});

		btnCloseSide?.addEventListener('click', () => {
			setSidePanelState(false);
		});

		// Switch Active App Tab
		function switchAppTab(tabKey: string) {
			if (sidePanelOpen && activeTab === tabKey) {
				// Clicking active tab toggles panel
				setSidePanelState(false);
				return;
			}

			activeTab = tabKey;
			setSidePanelState(true);

			// Highlight active app button
			sideAppBtns.forEach((btn) => {
				const key = btn.getAttribute('data-tab');
				if (key === tabKey) {
					btn.classList.add('ring-2', 'ring-primary', 'bg-base-200');
				} else {
					btn.classList.remove('ring-2', 'ring-primary', 'bg-base-200');
				}
			});

			renderActiveDeliverable();
		}

		sideAppBtns.forEach((btn) => {
			btn.addEventListener('click', () => {
				const key = btn.getAttribute('data-tab') || 'battlecards';
				switchAppTab(key);
			});
		});

		// Render Active Deliverable
		function renderActiveDeliverable() {
			if (!sideDeliverableView) return;

			const titles: Record<string, string> = {
				battlecards: '🎴 Objection Battlecards',
				presentation: '📊 Pitch Presentation Deck',
				email: '✉️ Executive Proposal Email',
				flowchart: '🗺️ Mutual Action Plan (MAP)',
				suite: '🏨 Buyer Deal Room Suite'
			};

			if (sidePanelTitle) {
				sidePanelTitle.textContent = titles[activeTab] || 'Deliverables Preview';
			}

			// Update Redirection Target & Text
			if (btnOpenFullPage && fullPageBtnText) {
				if (activeTab === 'battlecards') {
					btnOpenFullPage.href = '/battlecards';
					fullPageBtnText.textContent = 'Open Full Deck ↗';
				} else if (activeTab === 'presentation') {
					btnOpenFullPage.href = '/presentations';
					fullPageBtnText.textContent = 'Open Full Slides (16:9) ↗';
				} else if (activeTab === 'email') {
					btnOpenFullPage.href = '/emails';
					fullPageBtnText.textContent = 'Open Full Email ↗';
				} else if (activeTab === 'flowchart') {
					btnOpenFullPage.href = '/flowcharts';
					fullPageBtnText.textContent = 'Open Full MAP ↗';
				} else if (activeTab === 'suite') {
					const shareId = storedArtifacts.suite?.share_id || 'suite_live';
					btnOpenFullPage.href = `/suite/${shareId}`;
					fullPageBtnText.textContent = 'Open Buyer Room ↗';
				}
			}

			const art = storedArtifacts[activeTab];

			if (!art) {
				if (sideEmptyState) sideEmptyState.classList.remove('hidden');
				sideDeliverableView.classList.add('hidden');
				return;
			}

			if (sideEmptyState) sideEmptyState.classList.add('hidden');
			sideDeliverableView.classList.remove('hidden');

			if (sideActiveAccount) {
				sideActiveAccount.textContent = dealContext.account_name || 'Active Deal';
			}

			// BATTLECARDS: STACKED FLIPPABLE CAROUSEL
			if (activeTab === 'battlecards') {
				sideCards = art.content?.cards || [];
				sideCardOrder = sideCards.map((_, i) => i);

				sideDeliverableView.innerHTML = `
					<div class="space-y-4">
						<!-- Carousel Controls Bar -->
						<div class="flex items-center justify-between pb-2 border-b border-base-200">
							<div class="flex items-center gap-1.5 text-xs">
								<span class="badge badge-sm badge-neutral font-mono" id="side-deck-badge">Card 1 of ${sideCards.length}</span>
								<span class="text-base-content/60 text-[11px]">Click card to flip 🔄</span>
							</div>
							<div class="flex items-center gap-1">
								<button id="side-btn-flip" type="button" class="btn btn-xs btn-outline">
									Flip 🔄
								</button>
								<button id="side-btn-prev" type="button" class="btn btn-xs btn-outline w-7 h-7 rounded-full p-0 font-bold" title="Previous Card">
									❮
								</button>
								<button id="side-btn-next" type="button" class="btn btn-xs btn-neutral w-7 h-7 rounded-full p-0 font-bold" title="Next Card">
									❯
								</button>
							</div>
						</div>

						<!-- 3D Perspective Stack Stage -->
						<div class="relative w-full h-[370px] perspective-1000 my-2" id="side-deck-stage">
							<!-- Stack items injected below -->
						</div>

						<!-- Progress Dots -->
						<div class="flex items-center justify-center gap-1.5 pt-1" id="side-deck-dots"></div>
					</div>
				`;

				renderSideStackedDeck();
				setupSideDeckListeners();
				updateSideStackPositions();
				return;
			}

			// PRESENTATION: SLIDE DECK PREVIEW
			if (activeTab === 'presentation') {
				const slides = art.content?.slides || [];
				sideDeliverableView.innerHTML = `
					<div class="space-y-4">
						<div class="flex items-center justify-between pb-2 border-b border-base-200">
							<div>
								<h3 class="font-bold text-sm text-base-content">Pitch Deck (16:9 Presentation)</h3>
								<span class="text-[11px] text-base-content/60 font-mono">${art.deal_context?.account_name || 'Enterprise'} (${slides.length} Widescreen Slides)</span>
							</div>
							<a href="/presentations" class="btn btn-xs btn-outline">Launch 16:9 Deck ↗</a>
						</div>
						<div class="space-y-3">
							${slides.map((s: any) => `
								<div class="card bg-base-200/80 border border-base-300 p-4 rounded-xl space-y-2">
									<div class="flex items-center justify-between">
										<span class="badge badge-xs badge-neutral font-semibold">${s.tag || `Slide ${s.slide_number}`}</span>
										<span class="text-[10px] font-mono text-base-content/50">#${s.slide_number}</span>
									</div>
									<h4 class="font-bold text-xs text-base-content">${s.title}</h4>
									<p class="text-[11px] text-base-content/75">${s.subtitle || ''}</p>
									<ul class="text-[11px] space-y-1 pt-1 text-base-content/85">
										${(s.bullets || []).map((b: string) => `<li class="flex items-start gap-1.5"><span class="text-primary font-bold">✓</span><span>${b}</span></li>`).join('')}
									</ul>
									${s.speaker_note ? `
										<div class="mt-2 p-2 bg-base-100 rounded-md text-[10px] text-base-content/70 italic border border-base-300/60">
											<span class="font-semibold not-italic">Speaker Note:</span> ${s.speaker_note}
										</div>
									` : ''}
								</div>
							`).join('')}
						</div>
					</div>
				`;
				return;
			}

			// EMAIL: EXECUTIVE PROPOSAL
			if (activeTab === 'email') {
				const email = art.content || {};
				sideDeliverableView.innerHTML = `
					<div class="space-y-4">
						<div class="flex items-center justify-between pb-2 border-b border-base-200">
							<div>
								<h3 class="font-bold text-sm text-base-content">Executive Proposal Email</h3>
								<span class="text-[11px] text-base-content/60 font-mono">To: ${email.to || dealContext.recipient || 'Buyer Sponsor'}</span>
							</div>
							<a href="/emails" class="btn btn-xs btn-outline">Full View ↗</a>
						</div>
						<div class="card bg-base-200/80 border border-base-300 p-4 rounded-xl space-y-3">
							<div class="border-b border-base-300/80 pb-2 flex items-center justify-between">
								<div>
									<span class="text-[10px] text-base-content/60 font-mono uppercase block">Subject</span>
									<h4 class="font-bold text-xs text-base-content">${email.subject || 'Proposal & Next Milestones'}</h4>
								</div>
								<button id="btn-copy-email" class="btn btn-xs btn-ghost gap-1" title="Copy to clipboard">
									📋 Copy
								</button>
							</div>
							<div class="text-[11px] text-base-content/85 whitespace-pre-line leading-relaxed bg-base-100 p-3.5 rounded-lg border border-base-300/80">
								${email.body || ''}
							</div>
							${email.key_takeaways?.length ? `
								<div class="flex flex-wrap gap-1 pt-1">
									${email.key_takeaways.map((t: string) => `<span class="badge badge-xs badge-neutral">${t}</span>`).join('')}
								</div>
							` : ''}
						</div>
					</div>
				`;

				const copyBtn = document.getElementById('btn-copy-email');
				copyBtn?.addEventListener('click', () => {
					navigator.clipboard.writeText(`${email.subject}\n\n${email.body}`);
					copyBtn.textContent = 'Copied ✓';
					setTimeout(() => { copyBtn.textContent = '📋 Copy'; }, 2000);
				});
				return;
			}

			// MAP: MUTUAL ACTION PLAN
			if (activeTab === 'flowchart') {
				const map = art.content || {};
				const stages = map.stages || [];
				sideDeliverableView.innerHTML = `
					<div class="space-y-4">
						<div class="flex items-center justify-between pb-2 border-b border-base-200">
							<div>
								<h3 class="font-bold text-sm text-base-content">Mutual Action Plan (MAP)</h3>
								<span class="text-[11px] text-base-content/60 font-mono">Target Close: ${map.target_close_date || 'End of Month'}</span>
							</div>
							<a href="/flowcharts" class="btn btn-xs btn-outline">Full Roadmap ↗</a>
						</div>
						<div class="space-y-2.5">
							${stages.map((st: any) => `
								<div class="card bg-base-200/80 border border-base-300 p-3.5 rounded-xl space-y-1.5">
									<div class="flex items-center justify-between">
										<span class="badge badge-xs ${st.status === 'completed' ? 'badge-success' : 'badge-neutral'} font-semibold">Stage ${st.stage_number}</span>
										<span class="text-[10px] font-mono text-base-content/60">${st.target_date || ''}</span>
									</div>
									<h4 class="font-bold text-xs text-base-content">${st.name}</h4>
									<p class="text-[11px] text-base-content/75">${st.description || ''}</p>
									<div class="text-[10px] text-base-content/60 font-mono pt-1 flex justify-between">
										<span>Owner: ${st.owner || 'AE'}</span>
										<span>Deliverable: ${st.deliverable || 'Approved'}</span>
									</div>
								</div>
							`).join('')}
						</div>
					</div>
				`;
				return;
			}

			// SUITE: BUYER DEAL ROOM
			if (activeTab === 'suite') {
				const suite = art;
				sideDeliverableView.innerHTML = `
					<div class="space-y-4">
						<div class="flex items-center justify-between pb-2 border-b border-base-200">
							<div>
								<h3 class="font-bold text-sm text-base-content">Buyer Deal Room Suite</h3>
								<span class="text-[11px] text-base-content/60 font-mono">Encrypted Guest Keycard</span>
							</div>
							<a href="/suite/${suite.share_id || 'suite_live'}" class="btn btn-xs btn-outline">Enter Room ↗</a>
						</div>
						<div class="card bg-gradient-to-br from-base-200 to-base-300 border-2 border-primary/50 p-5 rounded-2xl space-y-3">
							<div class="flex items-center justify-between">
								<span class="badge badge-xs badge-success font-semibold">Active Keycard</span>
								<span class="font-mono text-[11px] text-base-content/70">${suite.share_id || 'suite_live'}</span>
							</div>
							<h4 class="font-bold text-sm text-base-content">Penthouse Suite: ${dealContext.account_name || 'Enterprise'}</h4>
							<p class="text-[11px] text-base-content/75 leading-relaxed">
								Encrypted guest deal room for enterprise stakeholders to review objection talk-tracks, verified ROI metrics, and mutual milestones.
							</p>
							<a href="/suite/${suite.share_id || 'suite_live'}" class="btn btn-sm btn-neutral w-full font-semibold shadow-xs">
								Open Guest Suite 🏨
							</a>
						</div>
					</div>
				`;
				return;
			}
		}

		// STACKED BATTLECARDS CAROUSEL LOGIC
		function renderSideStackedDeck() {
			const stage = document.getElementById('side-deck-stage');
			if (!stage) return;
			stage.innerHTML = '';

			sideCards.forEach((c, idx) => {
				const tags = c.tags || c.proof_points || ['Verified'];
				const item = document.createElement('div');
				item.className = 'side-card-item absolute inset-0 transition-all duration-500 cursor-pointer select-none';
				item.setAttribute('data-index', idx.toString());

				item.innerHTML = `
					<div class="flip-card h-full w-full">
						<div class="flip-card-inner h-full w-full relative">
							<!-- FRONT -->
							<div class="absolute inset-0 backface-hidden p-5 rounded-2xl border-2 border-base-300 bg-base-100 flex flex-col justify-between shadow-xl">
								<div class="flex items-center justify-between border-b border-base-200 pb-2">
									<span class="badge badge-xs badge-neutral font-bold uppercase tracking-wider">${c.category || 'Objection'}</span>
									<span class="text-[10px] font-mono text-base-content/60">Click to Flip 🔄</span>
								</div>

								<div class="space-y-2 my-auto">
									<span class="text-[10px] font-bold uppercase tracking-wider text-base-content/60">Prospect Objection:</span>
									<h4 class="text-sm font-bold text-base-content leading-snug">
										"${c.objection_quote || c.objection}"
									</h4>
									<p class="text-[11px] text-base-content/75">
										Persona: ${c.buyer_persona || 'Executive Sponsor'}
									</p>
								</div>

								<div class="pt-2 border-t border-base-200 flex items-center justify-between text-[11px]">
									<div class="flex gap-1">
										${tags.slice(0, 1).map((t: string) => `<span class="badge badge-xs badge-outline">${t}</span>`).join('')}
									</div>
									<span class="font-semibold text-primary">Tap to reveal talk-track →</span>
								</div>
							</div>

							<!-- BACK -->
							<div class="absolute inset-0 backface-hidden rotate-y-180 p-5 rounded-2xl border-2 border-primary/40 bg-base-200 flex flex-col justify-between shadow-xl">
								<div class="flex items-center justify-between border-b border-base-300 pb-2">
									<span class="badge badge-xs badge-success font-bold">Winning Talk-Track</span>
									<span class="text-[10px] font-mono text-base-content/60">Tap to Flip Back ↺</span>
								</div>

								<div class="space-y-2 my-auto">
									<div class="text-[11px] text-base-content leading-relaxed bg-base-100 p-3 rounded-xl border border-base-300 font-medium">
										${c.winning_response || c.talk_track}
									</div>
									<div class="grid grid-cols-2 gap-1.5 text-[10px]">
										<div class="p-2 rounded-lg bg-base-100 border border-base-300">
											<span class="block text-base-content/60 uppercase font-mono">Proof:</span>
											<span class="font-semibold truncate">${(c.proof_points || ['Validated metrics'])[0]}</span>
										</div>
										<div class="p-2 rounded-lg bg-base-100 border border-base-300">
											<span class="block text-base-content/60 uppercase font-mono">Metric:</span>
											<span class="font-semibold">${c.key_metric || '< 60-day break-even'}</span>
										</div>
									</div>
								</div>

								<div class="pt-2 border-t border-base-300 flex items-center justify-between text-[10px]">
									<span class="text-base-content/70">AE Confidence:</span>
									<div class="flex gap-1">
										<button class="btn btn-xs btn-outline py-0 h-5">Practice</button>
										<button class="btn btn-xs btn-neutral py-0 h-5">Mastered ✓</button>
									</div>
								</div>
							</div>
						</div>
					</div>
				`;

				item.addEventListener('click', (e) => {
					const target = e.target as HTMLElement;
					if (target.tagName === 'BUTTON') return;
					if (sideCardOrder[0] === idx) {
						const flipCard = item.querySelector('.flip-card-inner');
						flipCard?.classList.toggle('is-flipped');
					}
				});

				stage.appendChild(item);
			});
		}

		function updateSideStackPositions() {
			const items = Array.from(document.querySelectorAll('.side-card-item')) as HTMLElement[];
			items.forEach((card, originalIdx) => {
				const pos = sideCardOrder.indexOf(originalIdx);
				const flipCard = card.querySelector('.flip-card-inner');

				if (pos === 0) {
					card.style.zIndex = '30';
					card.style.transform = 'translateY(0) scale(1)';
					card.style.opacity = '1';
					card.style.pointerEvents = 'auto';
				} else if (pos === 1) {
					card.style.zIndex = '20';
					card.style.transform = 'translateY(14px) scale(0.96)';
					card.style.opacity = '0.85';
					card.style.pointerEvents = 'none';
					flipCard?.classList.remove('is-flipped');
				} else if (pos === 2) {
					card.style.zIndex = '10';
					card.style.transform = 'translateY(28px) scale(0.92)';
					card.style.opacity = '0.65';
					card.style.pointerEvents = 'none';
					flipCard?.classList.remove('is-flipped');
				} else {
					card.style.zIndex = '0';
					card.style.transform = 'translateY(42px) scale(0.88)';
					card.style.opacity = '0';
					card.style.pointerEvents = 'none';
					flipCard?.classList.remove('is-flipped');
				}
			});

			const badge = document.getElementById('side-deck-badge');
			if (badge && sideCards.length) {
				badge.textContent = `Card ${sideCardOrder[0] + 1} of ${sideCards.length}`;
			}

			const dotsContainer = document.getElementById('side-deck-dots');
			if (dotsContainer) {
				dotsContainer.innerHTML = '';
				sideCards.forEach((_, i) => {
					const dot = document.createElement('div');
					dot.className = `w-1.5 h-1.5 rounded-full transition-all ${sideCardOrder[0] === i ? 'bg-primary w-4' : 'bg-base-300'}`;
					dotsContainer.appendChild(dot);
				});
			}
		}

		function setupSideDeckListeners() {
			const btnNext = document.getElementById('side-btn-next');
			const btnPrev = document.getElementById('side-btn-prev');
			const btnFlip = document.getElementById('side-btn-flip');

			btnNext?.addEventListener('click', () => {
				if (!sideCards.length) return;
				const items = Array.from(document.querySelectorAll('.side-card-item')) as HTMLElement[];
				const activeCard = items[sideCardOrder[0]];
				const flipCard = activeCard.querySelector('.flip-card-inner');
				flipCard?.classList.remove('is-flipped');

				activeCard.style.transform = 'translateX(110%) rotate(12deg) scale(0.9)';
				activeCard.style.opacity = '0';

				setTimeout(() => {
					const first = sideCardOrder.shift()!;
					sideCardOrder.push(first);
					updateSideStackPositions();
				}, 250);
			});

			btnPrev?.addEventListener('click', () => {
				if (!sideCards.length) return;
				const items = Array.from(document.querySelectorAll('.side-card-item')) as HTMLElement[];
				const lastIdx = sideCardOrder[sideCardOrder.length - 1];
				const lastCard = items[lastIdx];
				const flipCard = lastCard.querySelector('.flip-card-inner');
				flipCard?.classList.remove('is-flipped');

				const last = sideCardOrder.pop()!;
				sideCardOrder.unshift(last);
				updateSideStackPositions();
			});

			btnFlip?.addEventListener('click', () => {
				if (!sideCards.length) return;
				const items = Array.from(document.querySelectorAll('.side-card-item')) as HTMLElement[];
				const activeCard = items[sideCardOrder[0]];
				const flipCard = activeCard?.querySelector('.flip-card-inner');
				flipCard?.classList.toggle('is-flipped');
			});
		}

		// Update App Badges on Side Dock
		function updateSideBadges() {
			const bc = storedArtifacts.battlecards?.content?.cards?.length || 0;
			if (appBadgeBc) {
				appBadgeBc.textContent = bc.toString();
				if (bc > 0) appBadgeBc.classList.remove('hidden');
			}

			const deck = storedArtifacts.presentation?.content?.slides?.length || 0;
			if (appBadgeDeck) {
				appBadgeDeck.textContent = deck.toString();
				if (deck > 0) appBadgeDeck.classList.remove('hidden');
			}

			const email = storedArtifacts.email ? 1 : 0;
			if (appBadgeEmail) {
				appBadgeEmail.textContent = email.toString();
				if (email > 0) appBadgeEmail.classList.remove('hidden');
			}

			const map = storedArtifacts.flowchart?.content?.stages?.length || 0;
			if (appBadgeMap) {
				appBadgeMap.textContent = map.toString();
				if (map > 0) appBadgeMap.classList.remove('hidden');
			}

			const suite = storedArtifacts.suite ? 1 : 0;
			if (appBadgeSuite) {
				appBadgeSuite.textContent = suite.toString();
				if (suite > 0) appBadgeSuite.classList.remove('hidden');
			}
		}

		// Append User Message
		function appendUserMessage(text: string) {
			if (!chatStream) return;
			if (welcomeTurn) welcomeTurn.classList.add('hidden');

			const turnDiv = document.createElement('div');
			turnDiv.className = 'flex justify-end';
			turnDiv.innerHTML = `
				<div class="p-3.5 sm:p-4 bg-neutral text-neutral-content rounded-2xl text-xs sm:text-sm font-medium leading-relaxed max-w-[85%] shadow-xs">
					${text}
				</div>
			`;
			chatStream.appendChild(turnDiv);
			chatStream.scrollTop = chatStream.scrollHeight;
		}

		// Append Progress Block
		function appendProgressBlock(): HTMLDivElement | null {
			if (!chatStream) return null;
			const progDiv = document.createElement('div');
			progDiv.className = 'p-4 bg-base-200/80 rounded-2xl border border-base-300 animate-pulse text-xs max-w-xl space-y-2';
			progDiv.innerHTML = `
				<div class="flex items-center gap-2 font-bold text-base-content">
					<span class="loading loading-spinner loading-xs text-primary"></span>
					<span>Analyzing deal directives & formulating plan...</span>
				</div>
				<div class="font-mono text-[11px] text-base-content/70 space-y-0.5">
					<div>● Evaluating competitive context & ROI requirements...</div>
					<div>● Dispatching deterministic tools to DAG engine...</div>
				</div>
			`;
			chatStream.appendChild(progDiv);
			chatStream.scrollTop = chatStream.scrollHeight;
			return progDiv;
		}

		// Append Agent Response with Smart Follow-up Questions
		function appendAgentTurn(data: any) {
			if (!chatStream) return;
			const turnDiv = document.createElement('div');
			turnDiv.className = 'space-y-3.5 max-w-3xl';

			// Update Deal Context
			if (data.deal_context) {
				dealContext = { ...dealContext, ...data.deal_context };
				if (dealTitleBadge) {
					dealTitleBadge.textContent = `${dealContext.account_name || 'Opportunity'} (${dealContext.deal_size || ''})`;
				}
			}

			// Store new artifacts and switch to side view
			const arts = data.artifacts || {};
			const newKeys = Object.keys(arts);
			if (newKeys.length > 0) {
				storedArtifacts = { ...storedArtifacts, ...arts };
				updateSideBadges();
				setSidePanelState(true);
				switchAppTab(newKeys[0]);
			}

			// Generated deliverables pill banner
			let generatedPillsHtml = '';
			if (newKeys.length > 0) {
				generatedPillsHtml = `
					<div class="flex flex-wrap items-center gap-1.5 pt-1">
						<span class="text-[11px] font-semibold text-base-content/70">Generated on Side:</span>
						${newKeys.map((k) => {
							const labels: Record<string, string> = {
								battlecards: '🎴 Battlecards',
								presentation: '📊 Pitch Deck',
								email: '✉️ Proposal Email',
								flowchart: '🗺️ Mutual Action Plan',
								suite: '🏨 Deal Suite'
							};
							return `
								<button class="side-inspect-pill btn btn-xs btn-neutral gap-1" data-tab="${k}">
									<span>${labels[k] || k}</span>
									<span>→</span>
								</button>
							`;
						}).join('')}
					</div>
				`;
			}

			// Follow-up Suggestions
			const followUps = data.follow_ups || [];
			let followUpsHtml = '';
			if (followUps.length > 0) {
				followUpsHtml = `
					<div class="mt-3 pt-3 border-t border-base-300 space-y-2">
						<div class="flex items-center gap-1.5 text-[11px] font-semibold text-base-content/75">
							<span>💡 Recommended Next Deliverables:</span>
						</div>
						<div class="flex flex-wrap gap-1.5">
							${followUps.map((fu: any) => `
								<button class="followup-chip btn btn-xs btn-outline rounded-full font-medium text-[11px] transition-all hover:btn-neutral" data-prompt="${fu.prompt}">
									${fu.label}
								</button>
							`).join('')}
						</div>
					</div>
				`;
			}

			turnDiv.innerHTML = `
				<div class="card bg-base-200/80 border-2 border-base-300 p-4 sm:p-5 rounded-2xl shadow-sm space-y-3">
					<div class="text-xs sm:text-sm text-base-content leading-relaxed whitespace-pre-line font-medium">
						${data.agent_reply || 'Plan executed.'}
					</div>
					${generatedPillsHtml}
					${followUpsHtml}
				</div>
			`;

			chatStream.appendChild(turnDiv);
			chatStream.scrollTop = chatStream.scrollHeight;

			// Attach listener to pills
			turnDiv.querySelectorAll('.side-inspect-pill').forEach((pill) => {
				pill.addEventListener('click', () => {
					const tabKey = pill.getAttribute('data-tab') || 'battlecards';
					switchAppTab(tabKey);
				});
			});

			// Attach listener to follow-up suggestion chips
			turnDiv.querySelectorAll('.followup-chip').forEach((chip) => {
				chip.addEventListener('click', () => {
					const prompt = chip.getAttribute('data-prompt');
					if (prompt) submitPrompt(prompt);
				});
			});
		}

		// Core Submit Prompt
		async function submitPrompt(promptText: string) {
			const text = promptText.trim();
			if (!text) return;

			if (chatInput) chatInput.value = '';
			appendUserMessage(text);
			const progBlock = appendProgressBlock();

			if (sendBtn) {
				sendBtn.setAttribute('disabled', 'true');
				sendBtn.innerHTML = '<span class="loading loading-spinner loading-xs"></span>';
			}

			try {
				const res = await fetch('/api/agent/run', {
					method: 'POST',
					headers: { 'Content-Type': 'application/json' },
					body: JSON.stringify({
						message: text,
						deal_context: dealContext,
					}),
				});

				if (!res.ok) throw new Error(`HTTP error ${res.status}`);
				const data = await res.json();
				if (progBlock) progBlock.remove();
				appendAgentTurn(data);
			} catch (err: any) {
				if (progBlock) progBlock.remove();
				const errDiv = document.createElement('div');
				errDiv.className = 'p-4 bg-error/15 text-error rounded-2xl text-xs border border-error/30';
				errDiv.textContent = `Encountered an issue executing deal instruction: ${err.message}`;
				chatStream?.appendChild(errDiv);
			} finally {
				if (sendBtn) {
					sendBtn.removeAttribute('disabled');
					sendBtn.innerHTML = 'Plan ⏎';
				}
			}
		}

		// Chat Form Submission
		chatForm?.addEventListener('submit', (e) => {
			e.preventDefault();
			if (chatInput) submitPrompt(chatInput.value);
		});

		// Starter Chips
		chips.forEach((chip) => {
			chip.addEventListener('click', () => {
				const prompt = chip.getAttribute('data-prompt');
				if (prompt) submitPrompt(prompt);
			});
		});

		// Reset Session
		resetBtn?.addEventListener('click', () => {
			dealContext = {};
			storedArtifacts = {};
			if (chatStream) {
				chatStream.innerHTML = '';
				if (welcomeTurn) chatStream.appendChild(welcomeTurn);
				welcomeTurn?.classList.remove('hidden');
			}
			if (dealTitleBadge) dealTitleBadge.textContent = 'New Opportunity';
			updateSideBadges();
			renderActiveDeliverable();
		});

		// Initialize
		updateSideBadges();
		switchAppTab('battlecards');
	</script>
</Layout>

