								<div class="bg-base-100 p-1 rounded border border-base-200">Sales: ${crustRes.headcount.department_breakdown.sales_and_marketing}</div>
								<div class="bg-base-100 p-1 rounded border border-base-200">Ops: ${crustRes.headcount.department_breakdown.operations_and_support}</div>
							</div>
						` : ''}
					</div>

					<!-- Funding & Valuation -->
					<div class="p-2.5 bg-base-200/50 rounded-lg border border-base-300/50 space-y-1">
						<div class="flex items-center justify-between">
							<span class="text-[10px] font-bold text-base-content/70 uppercase">Capital & Valuation</span>
							<span class="text-[10px] font-mono font-bold text-base-content">${crustRes.financials_and_funding?.stage_or_status || 'Enterprise'}</span>
						</div>
						<div class="text-[10px] text-base-content/85 font-mono">
