						${crustRes ? '🔄 Refresh Crustdata' : '⚡ Deep Research (Crustdata)'}
					</button>
				</div>
			</div>

			<!-- PRICING TRAPS & VULNERABILITIES -->
			${vulns.length > 0 ? `
				<div class="card bg-base-100 border border-base-300 p-4 rounded-xl space-y-2 shadow-2xs">
					<div class="flex items-center justify-between border-b border-base-200 pb-1.5">
