			<!-- DISPLACEMENT PLAYBOOK -->
			${comp.displacement_playbook ? `
				<div class="card bg-gradient-to-br from-base-200/90 to-base-100 border border-base-300 p-4 rounded-xl space-y-1.5 shadow-2xs">
					<div class="flex items-center justify-between border-b border-base-200 pb-1">
