						${comp.displacement_playbook}
					</p>
				</div>
			` : ''}
		</div>
	`;

	// Attach copy listeners for landmine questions
	sideDeliverableView.querySelectorAll('.comp-copy-btn').forEach((btn) => {
		btn.addEventListener('click', () => {
			const text = decodeURIComponent(btn.getAttribute('data-text') || '');
			if (text) {
				navigator.clipboard.writeText(text);
				const orig = btn.textContent;
				btn.textContent = 'Copied ✓';
				setTimeout(() => { btn.textContent = orig; }, 2000);
			}
		});
	});

	// Attach Crustdata Deep Research button listener
	const btnRunCrust = document.getElementById('btn-run-crustdata-research');
	btnRunCrust?.addEventListener('click', async () => {
		btnRunCrust.setAttribute('disabled', 'true');
		const origHtml = btnRunCrust.innerHTML;
		btnRunCrust.innerHTML = '<span class="loading loading-spinner loading-xs"></span> Querying Crustdata...';
		try {
			const res = await fetch('/api/competitor/deep-research', {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify({
					competitor: comp.competitor_name || dealContext.competitor || 'Competitor',
					account_name: dealContext.account_name || 'Enterprise',
				}),
			});
			if (res.ok) {
				const data = await res.json();
				if (data.artifact?.content) {
					if (!art.content) art.content = {};
					art.content.crustdata_research = data.artifact.content;
					renderActiveDeliverable();
				}
			}
		} catch (e) {
			console.error(e);
		} finally {
			btnRunCrust.removeAttribute('disabled');
			btnRunCrust.innerHTML = origHtml;
		}
	});

	return;
}

