/* Clean Markdown Content Styling */
.markdown-content {
  word-break: break-word;
  overflow-wrap: anywhere;
}
.markdown-content p {
  margin-bottom: 0.65rem;
  line-height: 1.6;
}
.markdown-content p:last-child {
  margin-bottom: 0;
}
.markdown-content h1 {
  font-size: 1.25rem;
  font-weight: 800;
  margin-top: 1rem;
  margin-bottom: 0.5rem;
