.markdown-content ol {
  list-style-type: decimal;
  padding-left: 1.25rem;
  margin-bottom: 0.65rem;
}
.markdown-content li {
  margin-bottom: 0.25rem;
  line-height: 1.5;
}
.markdown-content strong {
  font-weight: 700;
}
.markdown-content em {
  font-style: italic;
}
.markdown-content blockquote {
  border-left: 3px solid currentColor;
  padding-left: 0.75rem;
