}
.markdown-content pre code {
  padding: 0;
  background: transparent;
  font-size: inherit;
}
.markdown-content table {
  width: 100%;
  border-collapse: collapse;
  margin: 0.75rem 0;
  font-size: 0.825rem;
}
.markdown-content th,
.markdown-content td {
  border: 1px solid rgba(125, 125, 125, 0.2);
